  RPL_UNAWAY: "305",
  RPL_NOWAWAY: "306",
  RPL_WHOISUSER: "311",
  RPL_WHOISSERVER: "312",
  RPL_WHOISIDLE: "317",
  RPL_ENDOFWHOIS: "318",
  RPL_WHOISCHANNELS: "319",
  // 320 is not in RFC 2812. It is a de facto numeric used by ircu, UnrealIRCd
  // and Ergo for extra WHOIS information lines.
  RPL_WHOISSPECIAL: "320",
  RPL_LISTSTART: "321",
  RPL_LIST: "322",
  RPL_LISTEND: "323",
  RPL_CHANNELMODEIS: "324",
  RPL_NOTOPIC: "331",
  RPL_TOPIC: "332",
  RPL_INVITING: "341",
  RPL_NAMREPLY: "353",
  RPL_ENDOFNAMES: "366",
