  RPL_MOTDSTART: "375",
  RPL_ENDOFMOTD: "376",

  ERR_NOSUCHNICK: "401",
  ERR_NOSUCHCHANNEL: "403",
  ERR_CANNOTSENDTOCHAN: "404",
  ERR_NORECIPIENT: "411",
  ERR_NOTEXTTOSEND: "412",
